#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)

void invert(inout vec2 p, inout float n, inout bool fund, vec2 c, vec2 r) {
    // Inversion in an ellipse
    vec2 q = p - c;
    vec2 qq = q * q, rr = r * r;
    if (rr.y * qq.x + rr.x * qq.y < rr.x * rr.y) {
        p = c + q * rr.x * rr.y / dot(qq, rr.yx);
        n ++;
        fund = false;
    }
}

float a, b;

vec4 getColor(vec2 p) {
    // Gets the color at a given pixel coordinate
    p = 1.5 * (2. * p - iResolution.xy) / iResolution.y;
    float n = 0.;
    bool fund;
    for (int i = 0; i < 50; i ++) {
        fund = true;

        invert(p, n, fund, vec2(a + b) * .5, vec2(a, b));
        invert(p, n, fund, vec2(-a - b, a + b) * .5, vec2(b, a));
        invert(p, n, fund, vec2(-a - b) * .5, vec2(a, b));
        invert(p, n, fund, vec2(a + b, -a - b) * .5, vec2(b, a));

        if (fund) break;
    }
    return vec4(mod(n, 2.));
}



// shadertoy emulation
#define  time iTime
#define  resolution iResolution.xy

// Emulate some GLSL ES 3.x


#define pi 3.14159

float func(float a, float b) {
    return tanh(a * b) / tanh(a);
}

float crv(float a, float b) {
    float tr = 2. * max(fract(b), fract(-b)) - 1.;
    tr *= tr * (3. - 2. * tr);
    return func(a, 1. - func(a, tr));
}

vec3 crv(float a, vec3 v) {
    return vec3(crv(a,v.x), crv(a, v.y), crv(a, v.z));
}

float thc(float a, float b) {
    return func(a, cos(b));
}


vec3 pal( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b * crv(4., 6.28318*(c*t+d) ); // dont think 2pi is needed 
}

float h21 (vec2 a) {
    return fract(sin(dot(a.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}
